        assertNotNull(builder1, "builder() should not return null");

        Object builder2 = DeprecatedAttributes.builder();
        assertNotNull(builder2, "builder() should not return null on subsequent call");

        // Both should be instances of the same nested Builder class
        Class<?> builderClass1 = builder1.getClass();
