        // Each call to builder() should return a fresh instance (not a singleton)
        assertNotSame(builder1, builder2, "builder() should return a new Builder instance each time");
    }

    @Test
    public void testPrivateConstructorAndPublicGetters() throws Exception {
        // Obtain private constructor DeprecatedAttributes(String, String, boolean)
        Constructor<DeprecatedAttributes> ctor =
                DeprecatedAttributes.class.getDeclaredConstructor(String.class, String.class, boolean.class);
        ctor.setAccessible(true);

        DeprecatedAttributes instance = ctor.newInstance("a description", "sinceX", true);
        assertEquals("a description", instance.getDescription(), "getDescription should return the set value");
        assertEquals("sinceX", instance.getSince(), "getSince should return the set value");
        assertTrue(instance.isForRemoval(), "isForRemoval should return the set boolean value");
    }

