        Object resultNull = toEmpty.invoke(instance, new Object[]{null});
        assertEquals("", resultNull, "toEmpty(null) should return empty string");

        // When passing a non-empty string, expect it returned unchanged
        Object resultNonEmpty = toEmpty.invoke(instance, "nonEmpty");
        assertEquals("nonEmpty", resultNonEmpty, "toEmpty(nonEmpty) should return the same string");
    }

    @Test
    public void testDefaultFieldValues() throws Exception {
